110	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
111	    @Override
112	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
113	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
114	        if (normalizedTelephone == null) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        String normalizedAddress = Owner.normalizeAddress(ownerFieldsDto.getAddress());
118	        if (normalizedAddress == null || normalizedAddress.isBlank()) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        if (!this.clinicService.findOwnerByTelephone(normalizedTelephone).isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.CONFLICT);
123	        }
124	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
125	            return new ResponseEntity<>(HttpStatus.CONFLICT);
126	        }
127	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
128	        LocalDate effectiveDate =
129	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
130	        LocalDate registrationDate = toBusinessDay(effectiveDate);
131	        if (countOwnersRegisteredOn(registrationDate) >= 100) {
132	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
133	        }
134	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
135	        List<Owner> householdMembers =
136	            findHouseholdMembers(ownerFieldsDto.getLastName(), normalizedAddress);
137	        if (!sharesHousehold && !householdMembers.isEmpty()) {
138	            return new ResponseEntity<>(HttpStatus.CONFLICT);
139	        }
140	        HttpHeaders headers = new HttpHeaders();
141	        owner.setTelephone(normalizedTelephone);
142	        owner.setRegistrationDate(registrationDate);
143	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
144	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
145	        if (sharesHousehold && !householdMembers.isEmpty()) {
146	            String householdId = householdId(owner.getLastName(), normalizedAddress);
147	            owner.setHouseholdId(householdId);
148	            for (Owner member : householdMembers) {
149	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
150	                    member.setHouseholdId(householdId);
151	                    this.clinicService.saveOwner(member);
152	                }
153	            }
154	        }
155	        this.clinicService.saveOwner(owner);
156	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
157	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
158	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
159	        headers.setLocation(UriComponentsBuilder.newInstance()
160	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
161	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
162	    }
