244	            .buildAndExpand(visit.getId()).toUri());
245	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
246	    }
247	
248	
249	    /**
250	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
251	     * stripped. When a leading {@code '+'} and country code are present they are kept;
252	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
253	     * is dropped from the national digits. The result must be a {@code '+'} followed
254	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
255	     * is returned to signal a bad request.
256	     */
257	    /**
258	     * Build the customer code for a newly created owner, formatted
259	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
260	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
261	     * the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to
262	     * one more than the number of owners already in that city.
263	     */
264	    private String nextCustomerCode(String city, String lastName) {
265	        String cityPrefix = prefixThree(city);
266	        String lastNamePrefix = prefixThree(lastName);
267	        String normalizedCity = normalizeForHousehold(city);
268	        int sequence = (int) this.clinicService.findAllOwners().stream()
269	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
270	            .count() + 1;
271	        return String.format("%s-%s-%04d", cityPrefix, lastNamePrefix, sequence);
272	    }
273	
274	    /**
275	     * Count the existing owners whose city matches the given one, compared after
276	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
277	     * cap: a city that already holds this many owners is at capacity.
278	     */
279	    private long countOwnersInCity(String city) {
280	        String normalizedCity = normalizeForHousehold(city);
281	        return this.clinicService.findAllOwners().stream()
282	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
283	            .count();
284	    }
285	
286	    /**
287	     * Count the existing owners whose registration date falls on the given day. Used to
288	     * enforce the per-day create limit: once this many owners have been registered today,
289	     * the day is at capacity and further creates are rejected.
290	     */
291	    private long countOwnersRegisteredOn(LocalDate day) {
292	        return this.clinicService.findAllOwners().stream()
293	            .filter(existing -> day.equals(existing.getRegistrationDate()))
294	            .count();
295	    }
296	
297	    /**
298	     * Roll a registration date forward to the next business day: a date falling on a
299	     * Saturday or Sunday is advanced to the following Monday, while a weekday is
300	     * returned unchanged.
301	     */
302	    private LocalDate toBusinessDay(LocalDate date) {
303	        DayOfWeek dayOfWeek = date.getDayOfWeek();
304	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
305	            return date.plusDays(8 - dayOfWeek.getValue());
306	        }
307	        return date;
308	    }
309	
310	    /** Upper-cased first three letters of {@code value} (fewer if shorter, empty if null). */
311	    private String prefixThree(String value) {
312	        String v = value == null ? "" : value;
313	        return v.substring(0, Math.min(3, v.length())).toUpperCase(Locale.ROOT);
314	    }
315	
316	    /**
317	     * Find the existing owners that already belong to the same household as the given
318	     * last name and address, i.e. those sharing both fields. Both are compared
319	     * case-insensitively after collapsing runs of whitespace to a single space and
320	     * trimming the ends.
321	     */
322	    private List<Owner> findHouseholdMembers(String lastName, String address) {
323	        String normalizedLastName = normalizeForHousehold(lastName);
324	        String normalizedAddress = normalizeForHousehold(address);
325	        return this.clinicService.findAllOwners().stream()
326	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
327	                && normalizeForHousehold(existing.getAddress()).equals(normalizedAddress))
328	            .toList();
329	    }
330	
331	    /**
332	     * Count the existing owners that already share both the given first and last
333	     * name, compared case-insensitively. Used to populate an owner's namesake count
334	     * at creation time, reflecting how many owners with the same name existed before
335	     * this one was created.
336	     */
337	    private int countNamesakes(String firstName, String lastName) {
338	        String normalizedFirstName = normalizeName(firstName);
339	        String normalizedLastName = normalizeName(lastName);
340	        return (int) this.clinicService.findAllOwners().stream()
341	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
342	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
343	            .count();
344	    }
345	
346	    private String normalizeName(String value) {
347	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
348	    }
349	
350	    /**
351	     * Build a stable identifier shared by all owners of one household. It is derived
352	     * deterministically from the normalized last name and address, so every owner at
353	     * the same household resolves to the same value regardless of creation order.
354	     */
355	    private String householdId(String lastName, String address) {
356	        String key = normalizeForHousehold(lastName) + "\n" + normalizeForHousehold(address);
357	        try {
358	            byte[] digest = MessageDigest.getInstance("SHA-256")
359	                .digest(key.getBytes(StandardCharsets.UTF_8));
360	            StringBuilder sb = new StringBuilder();
361	            for (int i = 0; i < 6; i++) {
362	                sb.append(String.format("%02X", digest[i]));
363	            }
364	            return "HH-" + sb;
365	        }
366	        catch (NoSuchAlgorithmException e) {
367	            throw new IllegalStateException(e);
368	        }
369	    }
370	
371	    private String normalizeForHousehold(String value) {
372	        if (value == null) {
373	            return "";
374	        }
375	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
376	    }
377	
378	    private String normalizeTelephone(String telephone) {
379	        if (telephone == null) {
380	            return null;
381	        }
382	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
383	        String digits;
384	        if (cleaned.startsWith("+")) {
385	            digits = cleaned.substring(1);
386	        } else {
387	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
388	            digits = "61" + national;
389	        }
390	        return digits.matches("[0-9]{8,15}") ? "+" + digits : null;
391	    }
392	
393	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
394	    @Override
395	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
396	        Owner owner = this.clinicService.findOwnerById(ownerId);
397	        if (owner != null) {
398	            Pet pet = owner.getPet(petId);
399	            if (pet != null) {
400	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
401	            }
402	        }
403	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
404	    }
405	}
